@using sv_cf4456f4d38e46d5b4486bd0b84ec127.Services

<div class="settings-sidebar">
    <h2 class="sidebar-title">Settings</h2>
    <nav class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                    @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span>@section</span>
            </button>
        }
    </nav>
</div>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_cf4456f4d38e46d5b4486bd0b84ec127.Services

<div class="change-password-panel">
    <button class="panel-toggle" @onclick="() => IsExpanded = !IsExpanded">
        <span>Change Password</span>
        <span class="toggle-icon">@(IsExpanded ? "▲" : "▼")</span>
    </button>

    @if (IsExpanded)
    {
        <div class="panel-content">
            <div class="form-group">
                <label>Current Password</label>
                <input type="password" @bind="CurrentPassword" class="form-input" />
            </div>
            <div class="form-group">
                <label>New Password</label>
                <input type="password" @bind="NewPassword" class="form-input" />
            </div>
            <div class="form-group">
                <label>Confirm New Password</label>
                <input type="password" @bind="ConfirmPassword" class="form-input" />
            </div>

            @if (!string.IsNullOrEmpty(ErrorMessage))
            {
                <div class="message error">@ErrorMessage</div>
            }
            @if (!string.IsNullOrEmpty(SuccessMessage))
            {
                <div class="message success">@SuccessMessage</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@IsUpdating">
                @(IsUpdating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string current, string newPass)> OnChangePassword { get; set; }

    private bool IsExpanded;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? ErrorMessage;
    private string? SuccessMessage;
    private bool IsUpdating;

    private async Task UpdatePassword()
    {
        ErrorMessage = null;
        SuccessMessage = null;

        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            ErrorMessage = "New passwords do not match.";
            return;
        }

        if (NewPassword.Length < 8)
        {
            ErrorMessage = "New password must be at least 8 characters.";
            return;
        }

        IsUpdating = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            SuccessMessage = "Password updated successfully.";
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch (Exception ex)
        {
            ErrorMessage = ex.Message;
        }
        finally
        {
            IsUpdating = false;
        }
    }
}

@using sv_cf4456f4d38e46d5b4486bd0b84ec127.Services

<div class="active-sessions">
    <h4>Active Sessions</h4>
    <table class="sessions-table">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th>Action</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@FormatLastActive(session.LastActive)</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">
                                Revoke
                            </button>
                        }
                        else
                        {
                            <span class="current-badge">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>

    @if (SessionToRevoke is not null)
    {
        <div class="confirmation-dialog-overlay">
            <div class="confirmation-dialog">
                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> from <strong>@SessionToRevoke.Location</strong>?</p>
                <div class="dialog-actions">
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button class="btn btn-danger" @onclick="DoRevoke">Revoke Session</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? SessionToRevoke;

    private void ConfirmRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        SessionToRevoke = null;
    }

    private async Task DoRevoke()
    {
        if (SessionToRevoke is not null)
        {
