@using sv_cf4456f4d38e46d5b4486bd0b84ec127.Services
@inject ISettingsService SettingsService

<div class="settings-section profile-section">
    <h3>Profile Settings</h3>

    @if (IsLoading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="avatar-preview">
            <img src="@AvatarUrl" alt="Avatar" class="avatar-image" />
            <div class="form-group">
                <label>Avatar URL</label>
                <input type="text" @bind="AvatarUrl" class="form-input" />
            </div>
        </div>

        <div class="form-group">
            <label>Display Name</label>
            <input type="text" @bind="DisplayName" class="form-input" />
        </div>

        <div class="form-group">
            <label>Email</label>
            <input type="email" @bind="Email" class="form-input" />
        </div>

        <div class="form-group">
            <label>Bio</label>
            <textarea @bind="Bio" class="form-input form-textarea" rows="4"></textarea>
        </div>

        @if (!string.IsNullOrEmpty(Message))
        {
            <div class="message success">@Message</div>
        }

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveChanges" disabled="@IsSaving">
                @(IsSaving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-secondary" @onclick="DiscardChanges">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    private string DisplayName = "";
    private string Email = "";
    private string AvatarUrl = "";
    private string Bio = "";
    private UserProfile? SavedProfile;
    private bool IsLoading = true;
    private bool IsSaving;
    private string? Message;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        IsLoading = true;
        SavedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(SavedProfile);
        IsLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        AvatarUrl = profile.AvatarUrl;
        Bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        IsSaving = true;
        Message = null;
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await SettingsService.SaveProfileAsync(updated);
        SavedProfile = updated;
        Message = "Profile saved successfully!";
        IsSaving = false;
    }

    private void DiscardChanges()
    {
        Message = null;
        if (SavedProfile is not null)
        {
            ApplyProfile(SavedProfile);
        }
    }
}

@using sv_cf4456f4d38e46d5b4486bd0b84ec127.Services
@inject ISettingsService SettingsService

<div class="settings-section notifications-section">
    <h3>Notification Preferences</h3>

    @if (IsLoading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <span>Email Notifications</span>
                <input type="checkbox" @bind="EmailNotifications" class="toggle-switch" />
            </label>

            <label class="toggle-item">
                <span>Push Notifications</span>
                <input type="checkbox" @bind="PushNotifications" class="toggle-switch" />
            </label>

            <label class="toggle-item">
                <span>Weekly Digest</span>
                <input type="checkbox" @bind="WeeklyDigest" class="toggle-switch" />
            </label>
        </div>

        <div class="channels-section">
            <h4>Muted Channels</h4>
            @foreach (var channel in AllChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@MutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span>#@channel</span>
                </label>
            }
        </div>

        @if (!string.IsNullOrEmpty(Message))
        {
            <div class="message success">@Message</div>
        }

        <button class="btn btn-primary" @onclick="SavePreferences" disabled="@IsSaving">
            @(IsSaving ? "Saving..." : "Save Preferences")
        </button>
    }
</div>

@code {
    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private List<string> MutedChannels = new();
    private bool IsLoading = true;
    private bool IsSaving;
    private string? Message;

    private static readonly List<string> AllChannels = new() { "general", "announcements", "marketing", "engineering", "random" };

    protected override async Task OnInitializedAsync()
    {
        IsLoading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        EmailNotifications = prefs.EmailNotifications;
        PushNotifications = prefs.PushNotifications;
        WeeklyDigest = prefs.WeeklyDigest;
        MutedChannels = new List<string>(prefs.MutedChannels);
        IsLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!isMuted)
            MutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        IsSaving = true;
        Message = null;
        var prefs = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        Message = "Preferences saved successfully!";
        IsSaving = false;
    }
}

@using sv_cf4456f4d38e46d5b4486bd0b84ec127.Services
@inject ISettingsService SettingsService

<div class="settings-section security-section">
    <h3>Security Settings</h3>

    @if (IsLoading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <div class="two-factor-section">
            <h4>Two-Factor Authentication</h4>
            <div class="two-factor-status">
                <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                    @(TwoFactorEnabled ? "● Enabled" : "○ Disabled")
                </span>
                <label class="toggle-item">
                    <span>@(TwoFactorEnabled ? "Disable 2FA" : "Enable 2FA")</span>
                    <input type="checkbox" @bind="TwoFactorEnabled" class="toggle-switch" />
                </label>
            </div>
            @if (LastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <ActiveSessionsTable Sessions="Sessions" OnRevoke="HandleRevoke" />
    }
</div>

@code {
    private bool TwoFactorEnabled;
    private DateTime? LastPasswordChange;
    private List<ActiveSession> Sessions = new();
    private bool IsLoading = true;

    protected override async Task OnInitializedAsync()
    {
        IsLoading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        TwoFactorEnabled = settings.TwoFactorEnabled;
        LastPasswordChange = settings.LastPasswordChange;
        Sessions = settings.Sessions.ToList();
        IsLoading = false;
    }

    private async Task HandleChangePassword((string current, string newPass) args)
    {
        await SettingsService.ChangePasswordAsync(args.current, args.newPass);
        LastPasswordChange = DateTime.UtcNow;
    }

    private async Task HandleRevoke(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        Sessions = Sessions.Where(s => s.Id != sessionId).ToList();
    }
}

@using sv_cf4456f4d38e46d5b4486bd0b84ec127.Services
@inject ISettingsService SettingsService

<div class="settings-section appearance-section">
