    @if (IsLoading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(Theme == theme)"
                               @onchange="() => Theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(FontSize == size)"
                               @onchange="() => FontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label>Language</label>
            <select @bind="Language" class="form-input form-select">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
            </select>
        </div>

        <div class="toggle-group">
            <label class="toggle-item">
                <span>Compact Mode</span>
                <input type="checkbox" @bind="CompactMode" class="toggle-switch" />
            </label>
        </div>

        <div class="appearance-preview @Theme.ToLower() @(CompactMode ? "compact" : "") font-@FontSize.ToLower()">
            <h4>Live Preview</h4>
            <div class="preview-card">
                <p class="preview-heading">Sample Heading</p>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(Message))
        {
            <div class="message success">@Message</div>
        }

        <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@IsSaving">
            @(IsSaving ? "Saving..." : "Save")
        </button>
    }
</div>

