@using sv_cf4456f4d38e46d5b4486bd0b84ec127.Services
@inject ISettingsService SettingsService

<div class="settings-section notifications-section">
    <h3>Notification Preferences</h3>

    @if (IsLoading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <span>Email Notifications</span>
                <input type="checkbox" @bind="EmailNotifications" class="toggle-switch" />
            </label>

            <label class="toggle-item">
                <span>Push Notifications</span>
                <input type="checkbox" @bind="PushNotifications" class="toggle-switch" />
            </label>

            <label class="toggle-item">
                <span>Weekly Digest</span>
                <input type="checkbox" @bind="WeeklyDigest" class="toggle-switch" />
            </label>
        </div>

        <div class="channels-section">
            <h4>Muted Channels</h4>
            @foreach (var channel in AllChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@MutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <span>#@channel</span>
                </label>
            }
        </div>

        @if (!string.IsNullOrEmpty(Message))
        {
            <div class="message success">@Message</div>
        }

        <button class="btn btn-primary" @onclick="SavePreferences" disabled="@IsSaving">
            @(IsSaving ? "Saving..." : "Save Preferences")
        </button>
    }
</div>

@code {
    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private List<string> MutedChannels = new();
    private bool IsLoading = true;
    private bool IsSaving;
    private string? Message;

    private static readonly List<string> AllChannels = new() { "general", "announcements", "marketing", "engineering", "random" };

    protected override async Task OnInitializedAsync()
    {
        IsLoading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        EmailNotifications = prefs.EmailNotifications;
        PushNotifications = prefs.PushNotifications;
        WeeklyDigest = prefs.WeeklyDigest;
        MutedChannels = new List<string>(prefs.MutedChannels);
        IsLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!isMuted)
            MutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        IsSaving = true;
        Message = null;
        var prefs = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        Message = "Preferences saved successfully!";
        IsSaving = false;
    }
}

