+    font-weight: 500;
+    color: #4a4a6a;
+    margin-bottom: 0.375rem;
+}
+
+.form-input {
+    width: 100%;
+    padding: 0.625rem 0.875rem;
+    border: 1px solid #d1d1e0;
+    border-radius: 0.375rem;
+    font-size: 0.95rem;
+    transition: border-color 0.15s ease;
+    box-sizing: border-box;
+}
+
+.form-input:focus {
+    outline: none;
+    border-color: #4f46e5;
+    box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
+}
+
+.form-textarea {
+    resize: vertical;
+    min-height: 80px;
+}
+
+.form-select {
+    max-width: 300px;
+}
+
+/* Buttons */
+.btn {
+    padding: 0.625rem 1.25rem;
+    border: none;
+    border-radius: 0.375rem;
+    font-size: 0.9rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: all 0.15s ease;
+}
+
+.btn:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+.btn-primary {
+    background: #4f46e5;
+    color: #fff;
+}
+
+.btn-primary:hover:not(:disabled) {
+    background: #4338ca;
+}
+
+.btn-secondary {
+    background: #f0f0f8;
+    color: #4a4a6a;
+}
+
+.btn-secondary:hover:not(:disabled) {
+    background: #e0e0f0;
+}
+
+.btn-danger {
+    background: #ef4444;
+    color: #fff;
+}
+
+.btn-danger:hover:not(:disabled) {
+    background: #dc2626;
+}
+
+.btn-sm {
+    padding: 0.375rem 0.75rem;
+    font-size: 0.8rem;
+}
+
+.button-group {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+}
+
+/* Messages */
+.message {
+    padding: 0.75rem 1rem;
+    border-radius: 0.375rem;
+    margin: 1rem 0;
+    font-size: 0.9rem;
+}
+
+.message.success {
+    background: #ecfdf5;
+    color: #065f46;
+    border: 1px solid #a7f3d0;
+}
+
+.message.error {
+    background: #fef2f2;
+    color: #991b1b;
+    border: 1px solid #fecaca;
+}
+
+.loading {
+    color: #6b7280;
+    font-style: italic;
+}
+
+/* Toggle items */
+.toggle-group {
+    margin-bottom: 1.5rem;
+}
+
+.toggle-item {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 0.75rem 0;
+    border-bottom: 1px solid #f0f0f8;
+    cursor: pointer;
+}
+
+.toggle-item span {
+    font-size: 0.95rem;
+    color: #2a2a4e;
+}
+
+.toggle-switch {
+    width: 1.25rem;
+    height: 1.25rem;
+    cursor: pointer;
+}
+
+/* Profile Section */
+.avatar-preview {
+    display: flex;
+    align-items: flex-start;
+    gap: 1.5rem;
+    margin-bottom: 1.5rem;
+    padding-bottom: 1.5rem;
+    border-bottom: 1px solid #f0f0f8;
+}
+
+.avatar-image {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 3px solid #e8e8f8;
+}
+
+.avatar-preview .form-group {
+    flex: 1;
+}
+
+/* Channels */
+.channels-section {
+    margin: 1.5rem 0;
+    padding: 1rem;
+    background: #fafafa;
+    border-radius: 0.5rem;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.5rem 0;
+    cursor: pointer;
+    font-size: 0.9rem;
+    color: #4a4a6a;
+}
+
+/* Change Password Panel */
+.change-password-panel {
+    margin-bottom: 1.5rem;
+    border: 1px solid #e8e8f0;
+    border-radius: 0.5rem;
+    overflow: hidden;
+}
+
+.panel-toggle {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    width: 100%;
+    padding: 1rem 1.25rem;
+    border: none;
+    background: #fafafa;
+    cursor: pointer;
+    font-size: 0.95rem;
+    font-weight: 500;
+    color: #2a2a4e;
+}
+
+.panel-toggle:hover {
+    background: #f0f0f8;
+}
+
+.panel-content {
+    padding: 1.25rem;
+    border-top: 1px solid #e8e8f0;
+}
+
+/* Two-factor */
+.two-factor-section {
+    margin: 1.5rem 0;
+    padding: 1.25rem;
+    background: #fafafa;
+    border-radius: 0.5rem;
+}
+
+.two-factor-status {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    margin-bottom: 0.5rem;
+}
+
+.status-indicator {
+    font-weight: 500;
+    font-size: 0.9rem;
+}
+
+.status-indicator.enabled {
+    color: #059669;
+}
+
+.status-indicator.disabled {
+    color: #9ca3af;
+}
+
+.info-text {
+    font-size: 0.85rem;
+    color: #6b7280;
+    margin-top: 0.5rem;
+}
+
+/* Sessions Table */
+.active-sessions {
+    margin-top: 1.5rem;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.75rem;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #f0f0f8;
+}
+
+.sessions-table th {
+    font-weight: 600;
+    color: #4a4a6a;
+    font-size: 0.8rem;
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    background: #ecfdf5;
+    color: #059669;
+    padding: 0.25rem 0.5rem;
+    border-radius: 0.25rem;
+    font-weight: 500;
+}
+
+/* Confirmation Dialog */
+.confirmation-dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.confirmation-dialog {
+    background: #fff;
+    padding: 1.5rem;
+    border-radius: 0.75rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
+}
+
+.confirmation-dialog p {
+    margin-bottom: 1.25rem;
+    color: #2a2a4e;
+    line-height: 1.5;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    justify-content: flex-end;
+}
+
+/* Radio group */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+    margin-top: 0.5rem;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.375rem;
+    cursor: pointer;
+    font-size: 0.9rem;
+    color: #2a2a4e;
+}
+
+/* Appearance Preview */
+.appearance-preview {
+    margin: 1.5rem 0;
+    padding: 1.5rem;
+    border-radius: 0.75rem;
+    border: 2px dashed #d1d1e0;
+    transition: all 0.2s ease;
+}
+
+.appearance-preview h4 {
+    margin-bottom: 0.75rem;
+    font-size: 0.85rem;
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+    color: #6b7280;
+}
+
+.preview-card {
+    padding: 1rem;
+    border-radius: 0.5rem;
+    background: #f8f8fc;
+    border: 1px solid #e8e8f0;
+}
+
+.preview-heading {
+    font-weight: 600;
+    margin-bottom: 0.5rem;
+}
+
+.preview-text {
+    color: #4a4a6a;
+    margin-bottom: 0.75rem;
+    line-height: 1.5;
+}
+
+.preview-button {
+    padding: 0.5rem 1rem;
+    border: none;
+    border-radius: 0.375rem;
+    background: #4f46e5;
+    color: #fff;
+    font-size: 0.85rem;
+    cursor: pointer;
+}
+
+/* Preview theme variants */
+.appearance-preview.dark {
+    background: #1a1a2e;
+    border-color: #3a3a5e;
+}
+
+.appearance-preview.dark .preview-card {
+    background: #2a2a4e;
+    border-color: #3a3a5e;
+}
+
+.appearance-preview.dark .preview-heading {
+    color: #f0f0f8;
+}
+
+.appearance-preview.dark .preview-text {
+    color: #b0b0d0;
+}
+
+.appearance-preview.dark h4 {
+    color: #9090b0;
+}
+
+.appearance-preview.system {
+    background: linear-gradient(135deg, #fff 50%, #1a1a2e 50%);
+    border-color: #a0a0c0;
+}
+
+/* Preview font sizes */
+.appearance-preview.font-small .preview-heading {
+    font-size: 0.9rem;
+}
+
+.appearance-preview.font-small .preview-text {
+    font-size: 0.8rem;
+}
+
+.appearance-preview.font-medium .preview-heading {
+    font-size: 1.1rem;
+}
+
+.appearance-preview.font-medium .preview-text {
+    font-size: 0.95rem;
+}
+
+.appearance-preview.font-large .preview-heading {
+    font-size: 1.3rem;
+}
+
+.appearance-preview.font-large .preview-text {
+    font-size: 1.1rem;
+}
+
+/* Compact mode preview */
+.appearance-preview.compact .preview-card {
+    padding: 0.5rem;
+}
+
+.appearance-preview.compact .preview-heading {
+    margin-bottom: 0.25rem;
+}
+
+.appearance-preview.compact .preview-text {
+    margin-bottom: 0.375rem;
+}
+

